/* ============================================
   TABS COMPONENT
   Horizontal tab navigation with underline
   ============================================ */

/* A row that does not fit its container scrolls inline rather than running
   off the page: the tabs never wrap or shrink, the scrollbar is hidden (a
   swipe, a trackpad or the arrow keys, whose focus scrolls the tab into
   view, all move it), and the baseline is drawn as a background so the
   scroll container's clipping cannot cut the active underline that sits
   on it. */
.ds-tabs {
  display: inline-flex;
  align-items: stretch;
  gap: 0;
  max-width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
  background: linear-gradient(var(--color-bg-container-border), var(--color-bg-container-border)) bottom / 100% var(--border-025) no-repeat;
}

.ds-tabs::-webkit-scrollbar {
  display: none;
}

/* ============================================
   FULL WIDTH
   ============================================ */

.ds-tabs--full-width {
  display: flex;
  width: 100%;
}

/* Equal shares of the row, but never narrower than a label: past that the
   row scrolls like any other. */
.ds-tabs--full-width .ds-tabs__tab {
  flex: 1 1 0;
  min-width: max-content;
}

/* ============================================
   TAB BUTTON
   ============================================ */

.ds-tabs__tab {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--gap-200); /* 8px */
  padding: var(--padding-200) var(--padding-400); /* 8px 16px */
  border: none;
  flex: none;
  white-space: nowrap;
  border-bottom: var(--border-050) solid transparent;
  background: none;
  cursor: pointer;
  position: relative;

  /* Typography — paragraph em (medium weight) for clickable controls */
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);

  transition: color var(--motion-duration-base) var(--motion-ease-standard), border-color var(--motion-duration-base) var(--motion-ease-standard);
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

.ds-tabs--compact .ds-tabs__tab {
  padding: var(--padding-150) var(--padding-300); /* 6px 12px */
  font-size: var(--font-paragraph-sm-emphasis-size);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
}

.ds-tabs--compact .ds-tabs__icon {
  --icon-size: var(--icon-size-500);
}

/* ============================================
   LABEL
   ============================================ */

.ds-tabs__label {
  color: var(--color-text-tertiary);
  transition: color var(--motion-duration-base) var(--motion-ease-standard);
}

/* ============================================
   COUNT
   ============================================ */

.ds-tabs__count {
  color: var(--color-text-tertiary);
  font-variant-numeric: tabular-nums;
}

/* ============================================
   ICON
   ============================================ */

.ds-tabs__icon {
  --icon-size: var(--icon-size-600);
  color: var(--color-icon-secondary);
  transition: color var(--motion-duration-base) var(--motion-ease-standard);
}

/* ============================================
   DEFAULT (inactive) TAB
   ============================================ */

.ds-tabs__tab:not(.ds-tabs__tab--disabled):hover .ds-tabs__label {
  color: var(--color-text-primary);
}

.ds-tabs__tab:not(.ds-tabs__tab--disabled):hover .ds-tabs__icon {
  color: var(--color-icon-primary);
}

.ds-tabs__tab:not(.ds-tabs__tab--disabled):hover {
  border-bottom-color: var(--color-bg-container-secondary);
}

/* ============================================
   ACTIVE TAB
   ============================================ */

.ds-tabs__tab--active {
  border-bottom-color: var(--color-action-primary-bg);
}

.ds-tabs__tab--active .ds-tabs__label {
  color: var(--color-text-primary);
}

.ds-tabs__tab--active .ds-tabs__icon {
  color: var(--color-action-primary-bg);
}

.ds-tabs__tab--active:not(.ds-tabs__tab--disabled):hover {
  border-bottom-color: var(--color-action-primary-bg);
}

/* ============================================
   FOCUS STATE
   ============================================ */

.ds-tabs__tab:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
  border-radius: var(--radius-200);
}

/* ============================================
   DISABLED STATE
   ============================================ */

.ds-tabs__tab--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ============================================
   PANELS — rendered when the tabs carry content
   ============================================ */

.ds-tabs__panel {
  padding-block-start: var(--padding-500);
}

.ds-tabs__panel:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
  border-radius: var(--radius-200);
}

'use client';

import React, { useId, useState } from 'react';
import '../../behaviors/visually-hidden.css';
import './Tabs.css';
import '../../fonts/material-symbols.css';
import { logicalArrowKey, mirrorClass } from '../../behaviors/direction';
import { formatNumber } from '../../behaviors/locale';
import { useLocale } from '../../behaviors/LocaleProvider';

export interface Tab {
  /** Unique tab identifier */
  value: string;
  /** Display label */
  label: string;
  /** Optional icon — Material Symbol name (string) or custom element (ReactNode) */
  icon?: string | React.ReactNode;
  /** A count after the label (unread items, results), written in the resolved locale; the tab's name carries it through `countLabel`. */
  count?: number;
  /** Whether this tab is disabled */
  disabled?: boolean;
  /** The id of the `role="tabpanel"` element this tab shows, written as the tab's `aria-controls`. Set it when you render the panels yourself; with `content`, Tabs names its own panel and this id is used for it. */
  panelId?: string;
  /** What the tab shows. When any tab has content, Tabs renders a `role="tabpanel"` for each after the tab list, the selected one shown, each named by its tab. The panels are the tab list's siblings, with no wrapper, and the ref and `className` stay on the tab list. Leave it out to render the panels yourself. */
  content?: React.ReactNode;
}

/** Props owned by Tabs itself — everything else falls through to the tablist. */
type TabsOwnProps = {
  /** Array of tab definitions */
  tabs: Tab[];
  /**
   * Value of the selected tab, for a controlled set. Leave it undefined to let
   * the component keep its own selection, seeded from `defaultValue`.
   */
  value?: string;
  /**
   * Value of the tab selected on first render when the set is uncontrolled.
   * Falls back to the first enabled tab.
   */
  defaultValue?: string;
  /** Called with the value of the tab the user selects */
  onValueChange?: (value: string) => void;
  /**
   * Legacy name for `value`.
   *
   * @deprecated Use `value` instead.
   */
  activeTab?: string;
  /**
   * Legacy change callback; fires alongside `onValueChange`.
   *
   * @deprecated Use `onValueChange` instead.
   */
  onTabChange?: (value: string) => void;
  /** Visual size */
  size?: 'default' | 'compact';
  /** Whether tabs fill the available width */
  fullWidth?: boolean;
  /** What a screen reader hears after a tab's label for its count, given the count already written in the resolved locale. Defaults to ", 3"; say what it counts (", 3 unread") when the label does not. */
  countLabel?: (count: string) => string;
  /** The BCP 47 locale the tab counts are written in, such as `ar-EG`. Defaults to the nearest LocaleProvider's, else `en-US`. */
  locale?: string;
  /** Additional CSS classes */
  className?: string;
  /**
   * Legacy accessible-name prop for the tab list.
   *
   * @deprecated Pass the native `aria-label` attribute instead.
   */
  ariaLabel?: string;
};

export interface TabsProps
  extends TabsOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof TabsOwnProps | 'children'> {}

/**
 * Tabs switch between related views in one place.
 *
 * Forwards a ref to the `role="tablist"` element, which is the component's
 * only wrapper, and spreads unrecognised props onto it. The list is named
 * "Tabs" unless a native `aria-label` or `aria-labelledby` says otherwise.
 */
const defaultCountLabel = (count: string) => `, ${count}`;

export const Tabs = React.forwardRef<HTMLDivElement, TabsProps>(
  (
    {
      tabs,
      value,
      defaultValue,
      onValueChange,
      activeTab,
      onTabChange,
      size = 'default',
      fullWidth = false,
      locale: localeProp,
      countLabel = defaultCountLabel,
      className = '',
      ariaLabel,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-tabs';
    const baseId = useId();
    const ownsPanels = tabs.some((tab) => tab.content !== undefined);
    const tabId = (index: number) => `${baseId}-tab-${index}`;
    const panelIdOf = (tab: Tab, index: number) => tab.panelId ?? (ownsPanels ? `${baseId}-panel-${index}` : undefined);
    const locale = useLocale(localeProp);
    const sizeClass = `${baseClass}--${size}`;
    const fullWidthClass = fullWidth ? `${baseClass}--full-width` : '';

    // `activeTab` is the deprecated spelling of `value`.
    const controlledValue = value ?? activeTab;
    const isControlled = controlledValue !== undefined;
    const [internalValue, setInternalValue] = useState<string>(
      () => defaultValue ?? tabs.find((t) => !t.disabled)?.value ?? '',
    );
    const selectedValue = isControlled ? controlledValue : internalValue;

    const select = (next: string) => {
      if (!isControlled) setInternalValue(next);
      onValueChange?.(next);
      onTabChange?.(next);
    };

    const classes = [baseClass, sizeClass, fullWidthClass, className]
      .filter(Boolean)
      .join(' ');

    const handleKeyDown = (e: React.KeyboardEvent, index: number) => {
      const enabledTabs = tabs.filter((t) => !t.disabled);
      const currentEnabledIndex = enabledTabs.findIndex((t) => t.value === tabs[index].value);

      let targetTab: Tab | undefined;

      switch (logicalArrowKey(e.key, e.currentTarget)) {
        case 'ArrowRight':
          e.preventDefault();
          targetTab = enabledTabs[(currentEnabledIndex + 1) % enabledTabs.length];
          break;
        case 'ArrowLeft':
          e.preventDefault();
          targetTab = enabledTabs[(currentEnabledIndex - 1 + enabledTabs.length) % enabledTabs.length];
          break;
        case 'Home':
          e.preventDefault();
          targetTab = enabledTabs[0];
          break;
        case 'End':
          e.preventDefault();
          targetTab = enabledTabs[enabledTabs.length - 1];
          break;
      }

      if (targetTab) {
        select(targetTab.value);
        // Focus the new tab button
        const tabList = (e.target as HTMLElement).parentElement;
        const targetEl = tabList?.querySelector(
          `[data-tab-value="${CSS.escape(targetTab.value)}"]`,
        ) as HTMLElement | null;
        targetEl?.focus();
      }
    };

    const list = (
      <div
        aria-label={ariaLabel ?? 'Tabs'}
        {...rest}
        ref={ref}
        className={classes}
        role="tablist"
      >
        {tabs.map((tab, index) => {
          const isActive = tab.value === selectedValue;
          const tabClass = [
            `${baseClass}__tab`,
            isActive ? `${baseClass}__tab--active` : '',
            tab.disabled ? `${baseClass}__tab--disabled` : '',
          ]
            .filter(Boolean)
            .join(' ');

          return (
            <button
              key={tab.value}
              type="button"
              className={tabClass}
              role="tab"
              aria-selected={isActive}
              aria-disabled={tab.disabled}
              id={ownsPanels ? tabId(index) : undefined}
              aria-controls={panelIdOf(tab, index)}
              tabIndex={isActive ? 0 : -1}
              data-tab-value={tab.value}
              onClick={() => !tab.disabled && select(tab.value)}
              onKeyDown={(e) => handleKeyDown(e, index)}
            >
              {tab.icon &&
                (typeof tab.icon === 'string' ? (
                  <span className={`${baseClass}__icon material-symbols-rounded ${mirrorClass(tab.icon)}`} aria-hidden="true">
                    {tab.icon}
                  </span>
                ) : (
                  <span className={`${baseClass}__icon`} aria-hidden="true">
                    {tab.icon}
                  </span>
                ))}
              <span className={`${baseClass}__label`}>
                {tab.label}
                {tab.count !== undefined && (
                  <span className="ds-visually-hidden">{countLabel(formatNumber(tab.count, locale))}</span>
                )}
              </span>
              {tab.count !== undefined && (
                <span className={`${baseClass}__count`} aria-hidden="true">
                  {formatNumber(tab.count, locale)}
                </span>
              )}
            </button>
          );
        })}
      </div>
    );

    if (!ownsPanels) return list;
    return (
      <>
        {list}
        {tabs.map((tab, index) => (
          <div
            key={tab.value}
            id={panelIdOf(tab, index)}
            role="tabpanel"
            aria-labelledby={tabId(index)}
            hidden={tab.value !== selectedValue}
            tabIndex={0}
            className={`${baseClass}__panel`}
          >
            {tab.content}
          </div>
        ))}
      </>
    );
  },
);

Tabs.displayName = 'Tabs';
